"""`qc`: technical delivery checks per target. Files are generated by ffmpeg with known specs; loudness expectations come from the EBU Tech 3341 reference signal the generator writes and from a second meter (ffmpeg's loudnorm analysis), not from qc's own ebur128 reading."""

from __future__ import annotations

import json
import re
import subprocess

import pytest

from filmcraft import qc
from support import FFMPEG, ffmpeg, needs_ffmpeg, skill

pytestmark = needs_ffmpeg


def av(path, *, seconds=4, size="1920x1080", rate="30", lufs=-14.0, audio="tone", vcodec="libx264", profile="high", ar=48000, ac=2, acodec="aac", faststart=True):
    """A test movie whose sound is a 1 kHz sine at `lufs` dBFS peak on every channel: EBU Tech 3341 (case 1-2) defines that signal as reading the same number in LUFS, so the expected loudness comes from the standard, not from a meter. `audio='silent'` or None for the other cases."""
    args = ["-f", "lavfi", "-i", f"testsrc2=size={size}:rate={rate}:duration={seconds}"]
    amp = 10 ** (lufs / 20)
    if audio == "tone":
        wave = f"{amp:.6f}*sin(2*PI*1000*t)"
        args += ["-f", "lavfi", "-i", f"aevalsrc={'|'.join([wave] * ac)}:s={ar}:d={seconds}"]
    elif audio == "silent":
        args += ["-f", "lavfi", "-i", f"anullsrc=r={ar}:cl={'stereo' if ac == 2 else 'mono'}", "-t", str(seconds)]
    v = ["-c:v", vcodec] + (["-profile:v", profile, "-pix_fmt", "yuv420p"] if vcodec == "libx264" else [])
    a = ["-ac", str(ac), "-c:a", acodec] if audio else []
    mov = ["-movflags", "+faststart"] if faststart else []
    ffmpeg(*args, *v, *a, *mov, "-shortest", str(path))
    return path


def loudnorm_meter(path) -> float:
    """Integrated loudness from ffmpeg's loudnorm analysis pass, an independent meter from the ebur128 filter qc reads."""
    r = subprocess.run([FFMPEG, "-hide_banner", "-nostats", "-i", str(path), "-map", "0:a:0", "-af", "loudnorm=print_format=json", "-f", "null", "-"], capture_output=True, text=True)
    doc, _ = json.JSONDecoder().raw_decode(r.stderr[r.stderr.rfind("{"):])
    return float(doc["input_i"])


def run_qc(path, target, *extra):
    code, out, raw, err = skill("qc", str(path), "--target", target, *extra)
    assert out is not None, raw + err
    return code, out


def check(out, name):
    return next(c for c in out["checks"] if c["name"] == name)


# -- judgement boundaries (pure core) ------------------------------------------------------------------------------------

@pytest.mark.parametrize("lufs, verdict", [(-14.0, True), (-15.0, True), (-12.999, None), (-15.5, None), (-16.0, None), (-16.01, False), (-11.9, False)])
def test_loudness_bands_for_youtube(lufs, verdict):
    """-14 LUFS: within ±1 passes, within ±2 warns, beyond fails (the bands are inclusive)."""
    m = qc.Measurements(container="mp4", video_codec="h264", video_profile="High", width=1920, height=1080, fps=30.0, duration=10.0,
                        audio_codec="aac", audio_profile="LC", sample_rate=48000, channels=2, integrated=lufs, true_peak=-2.0,
                        moov_first=True, has_elst=False)
    r = qc.judge(m, "youtube")
    c = next(c for c in r["checks"] if c["name"] == "integrated_loudness")
    if verdict is True:
        assert c["pass"] is True and "integrated_loudness" not in r["warnings"] + r["failed"]
    elif verdict is None:
        assert c["pass"] is True and "integrated_loudness" in r["warnings"]
    else:
        assert c["pass"] is False and "integrated_loudness" in r["failed"]


def test_unmeasurable_values_are_null_with_a_reason_and_warn():
    m = qc.Measurements(container="mp4", video_codec="h264", video_profile="High", width=1080, height=1920, fps=30.0, duration=10.0,
                        audio_codec="aac", audio_profile="LC", sample_rate=48000, channels=2, integrated=None, true_peak=None,
                        loudness_reason="silent: no audio passes the -70 LUFS absolute gate", moov_first=True, has_elst=False)
    r = qc.judge(m, "shorts")
    c = check(r, "integrated_loudness")
    assert c["value"] is None and c["pass"] is None and "silent" in c["reason"]
    assert "integrated_loudness" in r["warnings"] and r["pass"] is True


# -- the command on real files -------------------------------------------------------------------------------------------

def test_a_youtube_master_passes_and_its_loudness_agrees_with_a_second_meter(tmp_path):
    f = av(tmp_path / "good.mp4")
    code, out = run_qc(f, "youtube", "--expect-size", "1920x1080", "--expect-fps", "30", "--expect-duration", "4")
    assert code == 0 and out["pass"] is True and out["failed"] == []
    measured = check(out, "integrated_loudness")["value"]
    assert measured == pytest.approx(loudnorm_meter(f), abs=0.5)
    assert measured == pytest.approx(-14.0, abs=0.3)
    assert check(out, "moov_position")["value"] == "start"


def test_a_wrong_master_fails_each_required_check_and_warns_on_advice(tmp_path):
    f = av(tmp_path / "bad.mov", size="1280x720", rate="25", lufs=-8.0, ar=44100, ac=1, faststart=False, profile="main")
    code, out = run_qc(f, "youtube", "--expect-size", "1920x1080", "--expect-fps", "30")
    assert code == 3 and out["pass"] is False
    assert {"container", "size", "fps", "integrated_loudness"} <= set(out["failed"])
    assert {"video_profile", "sample_rate", "channels"} <= set(out["warnings"])


def test_no_audio_stream_fails_and_loudness_is_null(tmp_path):
    f = av(tmp_path / "mute.mp4", audio=None)
    code, out = run_qc(f, "youtube")
    assert code == 3 and "audio" in out["failed"]
    c = check(out, "integrated_loudness")
    assert c["value"] is None and "no audio stream" in c["reason"]


def test_silent_audio_is_unmeasurable_not_minus_infinity(tmp_path):
    f = av(tmp_path / "silent.mp4", audio="silent")
    code, out = run_qc(f, "youtube")
    c = check(out, "integrated_loudness")
    assert c["value"] is None and "silent" in c["reason"] and "integrated_loudness" in out["warnings"]
    assert check(out, "true_peak")["value"] is None


def test_warnings_alone_exit_zero(tmp_path):
    f = av(tmp_path / "quiet.mp4", lufs=-15.6)
    code, out = run_qc(f, "youtube")
    assert code == 0 and out["pass"] is True and "integrated_loudness" in out["warnings"]


def test_moov_at_the_end_warns_until_a_faststart_remux(tmp_path):
    f = av(tmp_path / "slow.mp4", faststart=False)
    code, out = run_qc(f, "youtube")
    assert check(out, "moov_position")["value"] == "end" and "moov_position" in out["warnings"]
    fixed = tmp_path / "fast.mp4"
    ffmpeg("-i", str(f), "-c", "copy", "-movflags", "+faststart", str(fixed))
    code, out = run_qc(fixed, "youtube")
    assert "moov_position" not in out["warnings"]


def test_vertical_targets_require_1080x1920(tmp_path):
    f = av(tmp_path / "wide.mp4")
    for target in ("shorts", "reels", "tiktok"):
        code, out = run_qc(f, target)
        assert code == 3 and "size" in out["failed"], target
    v = av(tmp_path / "tall.mp4", size="1080x1920")
    code, out = run_qc(v, "shorts")
    assert code == 0 and out["failed"] == []


def test_shorts_longer_than_the_platform_limit_fail(tmp_path):
    limit = qc.LIMITS["shorts"]["max_duration"]
    f = av(tmp_path / "long.mp4", size="1080x1920", rate="5", seconds=limit + 2)
    code, out = run_qc(f, "shorts")
    assert code == 3 and "duration" in out["failed"]


def test_duration_expectation_allows_one_frame(tmp_path):
    f = av(tmp_path / "d.mp4", seconds=4)
    code, out = run_qc(f, "youtube", "--expect-duration", str(4 + 1 / 30))
    assert "duration" not in out["failed"]
    code, out = run_qc(f, "youtube", "--expect-duration", "4.2")
    assert "duration" in out["failed"]


def test_broadcast_kr_targets_minus_24(tmp_path):
    ok = av(tmp_path / "b24.mp4", lufs=-24.0)
    code, out = run_qc(ok, "broadcast-kr")
    assert code == 0 and "integrated_loudness" not in out["failed"]
    loud = av(tmp_path / "b14.mp4", lufs=-14.0)
    code, out = run_qc(loud, "broadcast-kr")
    assert code == 3 and "integrated_loudness" in out["failed"]


def test_unreadable_file_is_a_usage_error(tmp_path):
    (tmp_path / "x.mp4").write_text("not media")
    code, out, raw, err = skill("qc", str(tmp_path / "x.mp4"), "--target", "youtube")
    assert code == 2 and "x.mp4" in out["error"]


def test_help_carries_the_criteria_table_with_its_authority():
    code, out, raw, err = skill("qc", "--help")
    assert code == 0
    for word in ("youtube", "shorts", "reels", "tiktok", "broadcast-kr", "-14", "-24", "dBTP", "Prints:", "Exits:", "3"):
        assert word in raw, word
    assert re.search(r"regulation|platform spec|measured|practice|decision", raw)


# -- review findings ----------------------------------------------------------------------------------------------------

def test_an_expected_duration_does_not_lift_the_platform_limit(tmp_path):
    limit = qc.LIMITS["shorts"]["max_duration"]
    f = av(tmp_path / "long.mp4", size="1080x1920", rate="5", seconds=limit + 2)
    code, out = run_qc(f, "shorts", "--expect-duration", str(limit + 2))
    assert code == 3 and "duration" in out["failed"]


def test_a_truncated_trailing_box_does_not_crash_the_check(tmp_path):
    f = av(tmp_path / "t.mp4")
    with open(f, "ab") as fh:
        fh.write(bytes.fromhex("0000000166726565"))
    code, out = run_qc(f, "youtube")
    assert code in (0, 3) and out["checks"]


def test_the_users_own_loudness_target_replaces_the_default(tmp_path):
    f = av(tmp_path / "quiet.mp4", lufs=-18.0)
    code, out = run_qc(f, "youtube")
    assert "integrated_loudness" in out["failed"]
    code, out = run_qc(f, "youtube", "--lufs", "-18")
    assert code == 0 and "integrated_loudness" not in out["failed"] + out["warnings"]
    assert check(out, "integrated_loudness")["expected"] == -18.0


def test_an_expected_size_does_not_lift_the_targets_size(tmp_path):
    f = av(tmp_path / "wide.mp4")
    code, out = run_qc(f, "shorts", "--expect-size", "1920x1080")
    assert code == 3 and "size" in out["failed"]
